// 本界面用于手动输入定位信息(省+市), 由 uiTask 在收到 EV_LOCATION_KB 后加载。
// 与 ui_WiFi 同样的约定: 回调不自己隐藏/切换屏幕, 统一交出事件位由 uiTask 处理。

#include "ui.h"
#include "App.h"
#include "Task_Common.h"

lv_obj_t * ui_location = NULL;
lv_obj_t * ui_Keyboard2 = NULL;
lv_obj_t * ui_Label4 = NULL;
lv_obj_t * ui_TextArea4 = NULL;
lv_obj_t * ui_Button2 = NULL;
// event funtions
void ui_event_Keyboard2(lv_event_t * e)
{
    lv_event_code_t event_code = lv_event_get_code(e);

    if(event_code == LV_EVENT_READY) {
        /* 键盘上的"确认": 输入有效时由 Get_LocationInfo() 内部请求退回主界面 */
        Get_LocationInfo(e);
    }
}

void ui_event_TextArea4(lv_event_t * e)
{
    lv_event_code_t event_code = lv_event_get_code(e);

    if(event_code == LV_EVENT_FOCUSED) {
        _ui_flag_modify(ui_Keyboard2, LV_OBJ_FLAG_HIDDEN, _UI_MODIFY_FLAG_REMOVE);
        _ui_keyboard_set_target(ui_Keyboard2,  ui_TextArea4);
    }
    if(event_code == LV_EVENT_DEFOCUSED) {
        _ui_flag_modify(ui_Keyboard2, LV_OBJ_FLAG_HIDDEN, _UI_MODIFY_FLAG_ADD);
    }
    if(event_code == LV_EVENT_READY) {
        /* 软键盘上的"回车"把 READY 发给输入框(而不是键盘对象), 所以这里也要接 */
        Get_LocationInfo(e);
    }
}

void ui_event_Button2(lv_event_t * e)
{
    lv_event_code_t event_code = lv_event_get_code(e);

    if(event_code == LV_EVENT_CLICKED) {
        /* 取消输入: 不提交任何内容, 直接退回主界面 */
        xEventGroupSetBits(Task_Events(), EV_MAIN_SCREEN);
    }
}

// build funtions

