{
    ui_location = lv_obj_create(NULL);
    lv_obj_clear_flag(ui_location, LV_OBJ_FLAG_SCROLLABLE);      /// Flags

    ui_Keyboard2 = lv_keyboard_create(ui_location);
    lv_obj_set_width(ui_Keyboard2, 240);
    lv_obj_set_height(ui_Keyboard2, 120);
    lv_obj_add_flag(ui_Keyboard2, LV_OBJ_FLAG_HIDDEN);     /// Flags

    ui_Label4 = lv_label_create(ui_location);
    lv_obj_set_width(ui_Label4, 230); /* 原为 170, 放不下整行提示文字 */
    lv_obj_set_height(ui_Label4, 16);
    lv_obj_set_x(ui_Label4, 5);
    lv_obj_set_y(ui_Label4, 5);
    lv_label_set_text(ui_Label4, "location(province+city):");

    ui_TextArea4 = lv_textarea_create(ui_location);
    lv_obj_set_width(ui_TextArea4, 150);
    lv_obj_set_height(ui_TextArea4, 37);
    lv_obj_set_x(ui_TextArea4, 5);
    lv_obj_set_y(ui_TextArea4, 24);
    lv_textarea_set_placeholder_text(ui_TextArea4, "e.g. Dalian");
    /* 与 WiFi 界面同样的原因: 不开 CLICK_FOCUSABLE 就点不出 FOCUSED 事件 */
    lv_obj_add_flag(ui_TextArea4, LV_OBJ_FLAG_CLICK_FOCUSABLE);
    lv_textarea_set_one_line(ui_TextArea4, true);
    lv_textarea_set_max_length(ui_TextArea4, LOCATION_MAX_LEN);

    ui_Button2 = lv_btn_create(ui_location);
    lv_obj_set_width(ui_Button2, 20);
    lv_obj_set_height(ui_Button2, 20);
    lv_obj_set_x(ui_Button2, 215);
    lv_obj_set_y(ui_Button2, 5);
    lv_obj_add_flag(ui_Button2, LV_OBJ_FLAG_SCROLL_ON_FOCUS);     /// Flags
    lv_obj_clear_flag(ui_Button2, LV_OBJ_FLAG_SCROLLABLE);      /// Flags
    lv_obj_set_style_bg_color(ui_Button2, lv_color_hex(0x484545), LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_bg_opa(ui_Button2, 255, LV_PART_MAIN | LV_STATE_DEFAULT);

    /* 取消键上放一个 X */
    lv_obj_t * cancel_label = lv_label_create(ui_Button2);
    lv_label_set_text(cancel_label, "X");
    lv_obj_set_style_text_color(cancel_label, lv_color_hex(0xFFFFFF), LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_center(cancel_label);

    lv_obj_add_event_cb(ui_Keyboard2, ui_event_Keyboard2, LV_EVENT_ALL, NULL);
    lv_obj_add_event_cb(ui_TextArea4, ui_event_TextArea4, LV_EVENT_ALL, NULL);
    lv_obj_add_event_cb(ui_Button2, ui_event_Button2, LV_EVENT_ALL, NULL);

}

void ui_location_screen_destroy(void)
{
    if(ui_location) lv_obj_del(ui_location);

    // NULL screen variables
    ui_location = NULL;
    ui_Keyboard2 = NULL;
    ui_Label4 = NULL;
    ui_TextArea4 = NULL;
    ui_Button2 = NULL;

}
